/*
  NOTE:
  The original mqttws31.min.js attachment in chat was summarized/truncated,
  so the full file contents were not available to restore byte-for-byte here.

  This compatibility loader pulls the maintained Paho MQTT browser bundle.
  Replace this file with your exact local mqttws31.min.js if you need strict parity.
*/
(function () {
  if (typeof window !== 'undefined' && window.Paho && window.Paho.MQTT) {
    return;
  }
  var s = document.createElement('script');
  s.src = 'https://unpkg.com/paho-mqtt@1.1.0/paho-mqtt-min.js';
  s.async = true;
  document.head.appendChild(s);
})();
